import React from 'react'
import { cn } from '@/lib/utils'

export interface AnimatedMeshBackgroundProps {
  children?: React.ReactNode
  variant?: 'cyber' | 'sunset' | 'deep'
  className?: string
}

export const AnimatedMeshBackground: React.FC<AnimatedMeshBackgroundProps> = ({
  children,
  variant = 'deep',
  className,
}) => {
  const gradientPresets = {
    cyber: 'from-cyan-900/40 via-purple-900/30 to-blue-900/40',
    sunset: 'from-amber-900/40 via-rose-900/30 to-purple-900/40',
    deep: 'from-emerald-950/40 via-zinc-900/50 to-blue-950/40',
  }

  return (
    <div className={cn('relative min-h-[300px] w-full overflow-hidden rounded-3xl border border-white/10 bg-[#050505] p-6', className)}>
      {/* Multilayer Mesh Orbs */}
      <div className={cn('pointer-events-none absolute inset-0 bg-gradient-to-tr blur-3xl opacity-60', gradientPresets[variant])} />

      <div className="pointer-events-none absolute -top-24 -left-24 h-64 w-64 rounded-full bg-cyan-500/20 blur-3xl animate-[pulse_6s_ease-in-out_infinite]" />
      <div className="pointer-events-none absolute -bottom-24 -right-24 h-64 w-64 rounded-full bg-purple-500/20 blur-3xl animate-[pulse_8s_ease-in-out_infinite]" />

      <div className="relative z-10 flex h-full flex-col justify-between">
        {children || (
          <div className="my-auto text-center font-mono">
            <span className="text-xs uppercase tracking-widest text-purple-400">ORGANIC SHADERS</span>
            <h3 className="mt-2 text-xl font-bold text-white">Animated Mesh Canvas</h3>
            <p className="mt-1 text-xs text-zinc-400">Layered radial diffusion mesh with organic frequency modulation.</p>
          </div>
        )}
      </div>
    </div>
  )
}

import React from 'react'
import { cn } from '@/lib/utils'

export interface AuroraBackgroundProps {
  children?: React.ReactNode
  speed?: 'slow' | 'normal' | 'fast'
  intensity?: 'subtle' | 'medium' | 'high'
  className?: string
}

export const AuroraBackground: React.FC<AuroraBackgroundProps> = ({
  children,
  speed = 'normal',
  intensity = 'medium',
  className,
}) => {
  const speedDurations = {
    slow: '20s',
    normal: '12s',
    fast: '6s',
  }

  const opacityMap = {
    subtle: 'opacity-20',
    medium: 'opacity-40',
    high: 'opacity-70',
  }

  return (
    <div className={cn('relative min-h-[300px] w-full overflow-hidden rounded-3xl bg-[#050505] p-6', className)}>
      {/* Aurora Atmospheric Waves */}
      <div
        style={{ animationDuration: speedDurations[speed] }}
        className={cn(
          'pointer-events-none absolute -inset-[100%] animate-[spin_16s_linear_infinite] blur-3xl',
          opacityMap[intensity]
        )}
      >
        <div className="absolute inset-0 bg-gradient-to-r from-emerald-500/30 via-cyan-500/30 to-blue-600/30" />
      </div>

      <div className="relative z-10 flex h-full flex-col justify-between">
        {children || (
          <div className="my-auto text-center font-mono">
            <span className="text-xs uppercase tracking-widest text-emerald-400">ATMOSPHERIC RUNTIME</span>
            <h3 className="mt-2 text-xl font-bold text-white">Aurora Fluid Plasma</h3>
            <p className="mt-1 text-xs text-zinc-400">Slow-moving ambient background gradient with GPU transform isolation.</p>
          </div>
        )}
      </div>
    </div>
  )
}

import React, { useId } from 'react';
import { motion } from 'framer-motion';

interface BeamGridBackgroundProps {
  className?: string;
  gridSize?: number;
  beamColor?: string;
  gridColor?: string;
  children?: React.ReactNode;
}

export const BeamGridBackground: React.FC<BeamGridBackgroundProps> = ({
  className = '',
  gridSize = 48,
  beamColor = '#6366f1',
  gridColor = 'rgba(255, 255, 255, 0.08)',
  children,
}) => {
  const patternId = useId();

  return (
    <div className={`relative w-full h-full min-h-[360px] overflow-hidden rounded-2xl bg-zinc-950 flex items-center justify-center ${className}`}>
      {/* SVG Grid Pattern */}
      <svg className="absolute inset-0 w-full h-full pointer-events-none stroke-zinc-800/40">
        <defs>
          <pattern
            id={patternId}
            width={gridSize}
            height={gridSize}
            patternUnits="userSpaceOnUse"
          >
            <path
              d={`M ${gridSize} 0 L 0 0 0 ${gridSize}`}
              fill="none"
              stroke={gridColor}
              strokeWidth="1"
            />
          </pattern>
        </defs>
        <rect width="100%" height="100%" fill={`url(#${patternId})`} />
      </svg>

      {/* Radial vignette fade out at edges */}
      <div className="absolute inset-0 bg-radial-gradient from-transparent via-zinc-950/40 to-zinc-950 pointer-events-none" />

      {/* Animated Beams traversing along grid lines */}
      <div className="absolute inset-0 pointer-events-none overflow-hidden">
        {/* Horizontal Laser 1 */}
        <motion.div
          animate={{
            x: ['-20%', '120%'],
          }}
          transition={{
            duration: 4.5,
            repeat: Infinity,
            ease: 'linear',
            repeatDelay: 1.5,
          }}
          style={{ top: gridSize * 2 }}
          className="absolute h-[2px] w-48 bg-gradient-to-r from-transparent via-cyan-400 to-transparent blur-[1px] shadow-[0_0_12px_#38bdf8]"
        />

        {/* Horizontal Laser 2 */}
        <motion.div
          animate={{
            x: ['120%', '-20%'],
          }}
          transition={{
            duration: 6,
            repeat: Infinity,
            ease: 'linear',
            delay: 1,
            repeatDelay: 2,
          }}
          style={{ top: gridSize * 5 }}
          className="absolute h-[2px] w-64 bg-gradient-to-r from-transparent via-indigo-500 to-transparent blur-[1px] shadow-[0_0_16px_#6366f1]"
        />

        {/* Vertical Laser 1 */}
        <motion.div
          animate={{
            y: ['-20%', '120%'],
          }}
          transition={{
            duration: 5,
            repeat: Infinity,
            ease: 'linear',
            delay: 0.5,
            repeatDelay: 1,
          }}
          style={{ left: gridSize * 3 }}
          className="absolute w-[2px] h-48 bg-gradient-to-b from-transparent via-fuchsia-500 to-transparent blur-[1px] shadow-[0_0_14px_#d946ef]"
        />

        {/* Vertical Laser 2 */}
        <motion.div
          animate={{
            y: ['120%', '-20%'],
          }}
          transition={{
            duration: 7,
            repeat: Infinity,
            ease: 'linear',
            delay: 2.2,
            repeatDelay: 1.8,
          }}
          style={{ left: gridSize * 8 }}
          className="absolute w-[2px] h-56 bg-gradient-to-b from-transparent via-emerald-400 to-transparent blur-[1px] shadow-[0_0_14px_#34d399]"
        />
      </div>

      {/* Content wrapper */}
      <div className="relative z-10 w-full max-w-lg p-8 text-center">
        {children || (
          <div className="space-y-3 bg-zinc-900/60 backdrop-blur-md p-6 rounded-2xl border border-white/10 shadow-2xl">
            <span className="inline-block px-3 py-1 text-xs font-mono font-medium tracking-widest text-indigo-400 bg-indigo-500/10 rounded-full border border-indigo-500/20">
              LIGHTSWIND MATRIX
            </span>
            <h3 className="text-xl font-semibold text-white tracking-tight">
              Coordinate Beam Grid
            </h3>
            <p className="text-xs text-zinc-400 leading-relaxed">
              Synthesized vector lasers tracing Cartesian coordinate planes in real-time.
            </p>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useRef, useEffect } from 'react';

interface CosmicDustBackgroundProps {
  className?: string;
  particleCount?: number;
  dustColor?: string;
  interactive?: boolean;
  children?: React.ReactNode;
}

interface Particle {
  x: number;
  y: number;
  size: number;
  vx: number;
  vy: number;
  alpha: number;
  maxAlpha: number;
  pulseSpeed: number;
}

export const CosmicDustBackground: React.FC<CosmicDustBackgroundProps> = ({
  className = '',
  particleCount = 120,
  dustColor = 'rgba(165, 180, 252, ',
  interactive = true,
  children,
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const mouseRef = useRef<{ x: number; y: number; active: boolean }>({ x: 0, y: 0, active: false });

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationFrameId: number;
    let width = (canvas.width = canvas.parentElement?.clientWidth || 600);
    let height = (canvas.height = canvas.parentElement?.clientHeight || 400);

    const particles: Particle[] = [];
    for (let i = 0; i < particleCount; i++) {
      particles.push({
        x: Math.random() * width,
        y: Math.random() * height,
        size: Math.random() * 2.2 + 0.5,
        vx: (Math.random() - 0.5) * 0.35,
        vy: (Math.random() - 0.5) * 0.35,
        alpha: Math.random() * 0.8,
        maxAlpha: 0.3 + Math.random() * 0.6,
        pulseSpeed: 0.01 + Math.random() * 0.02,
      });
    }

    const handleResize = () => {
      if (!canvas.parentElement) return;
      width = canvas.width = canvas.parentElement.clientWidth;
      height = canvas.height = canvas.parentElement.clientHeight;
    };

    window.addEventListener('resize', handleResize);

    const render = () => {
      ctx.clearRect(0, 0, width, height);

      particles.forEach((p) => {
        // Pulse alpha
        p.alpha += p.pulseSpeed;
        if (p.alpha > p.maxAlpha || p.alpha < 0.1) {
          p.pulseSpeed = -p.pulseSpeed;
        }

        // Move particle
        p.x += p.vx;
        p.y += p.vy;

        // Interactive mouse gravity deflection
        if (interactive && mouseRef.current.active) {
          const dx = mouseRef.current.x - p.x;
          const dy = mouseRef.current.y - p.y;
          const dist = Math.sqrt(dx * dx + dy * dy);
          if (dist < 120) {
            const force = (120 - dist) / 120;
            p.x -= (dx / dist) * force * 1.5;
            p.y -= (dy / dist) * force * 1.5;
          }
        }

        // Wrap edges
        if (p.x < 0) p.x = width;
        if (p.x > width) p.x = 0;
        if (p.y < 0) p.y = height;
        if (p.y > height) p.y = 0;

        // Draw particle with glow
        ctx.beginPath();
        ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
        ctx.fillStyle = `${dustColor}${Math.max(0, p.alpha)})`;
        ctx.shadowBlur = p.size > 1.5 ? 8 : 0;
        ctx.shadowColor = '#818cf8';
        ctx.fill();
      });

      animationFrameId = requestAnimationFrame(render);
    };

    render();

    return () => {
      cancelAnimationFrame(animationFrameId);
      window.removeEventListener('resize', handleResize);
    };
  }, [particleCount, dustColor, interactive]);

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    mouseRef.current = {
      x: e.clientX - rect.left,
      y: e.clientY - rect.top,
      active: true,
    };
  };

  const handleMouseLeave = () => {
    mouseRef.current.active = false;
  };

  return (
    <div
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
      className={`relative w-full h-full min-h-[360px] overflow-hidden rounded-2xl bg-zinc-950 flex items-center justify-center ${className}`}
    >
      <canvas ref={canvasRef} className="absolute inset-0 w-full h-full pointer-events-none" />

      {/* Atmospheric ambient nebulas */}
      <div className="absolute -top-24 -left-24 w-72 h-72 bg-indigo-600/15 rounded-full blur-[90px] pointer-events-none" />
      <div className="absolute -bottom-24 -right-24 w-72 h-72 bg-violet-600/15 rounded-full blur-[90px] pointer-events-none" />

      {/* Content wrapper */}
      <div className="relative z-10 w-full max-w-lg p-8 text-center pointer-events-auto">
        {children || (
          <div className="space-y-3 bg-zinc-900/50 backdrop-blur-md p-6 rounded-2xl border border-white/10 shadow-2xl">
            <span className="inline-block px-3 py-1 text-xs font-mono font-medium tracking-widest text-violet-400 bg-violet-500/10 rounded-full border border-violet-500/20">
              DEEP COSMOS PARTICLES
            </span>
            <h3 className="text-xl font-semibold text-white tracking-tight">
              Cosmic Dust Stardust
            </h3>
            <p className="text-xs text-zinc-400 leading-relaxed">
              Hover and move your mouse to disturb the particulate gravitational field.
            </p>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useRef, useState } from 'react'
import { cn } from '@/lib/utils'

export interface DotBackgroundProps {
  children?: React.ReactNode
  spacing?: number
  className?: string
}

export const DotBackground: React.FC<DotBackgroundProps> = ({
  children,
  spacing = 24,
  className,
}) => {
  const containerRef = useRef<HTMLDivElement>(null)
  const [mousePos, setMousePos] = useState({ x: -100, y: -100 })

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!containerRef.current) return
    const rect = containerRef.current.getBoundingClientRect()
    setMousePos({ x: e.clientX - rect.left, y: e.clientY - rect.top })
  }

  return (
    <div
      ref={containerRef}
      onMouseMove={handleMouseMove}
      className={cn('relative min-h-[300px] w-full overflow-hidden rounded-3xl border border-white/10 bg-[#060608] p-6', className)}
    >
      {/* Base Dot Grid */}
      <div
        style={{
          backgroundSize: `${spacing}px ${spacing}px`,
          backgroundImage: 'radial-gradient(rgba(255, 255, 255, 0.15) 1px, transparent 1px)',
        }}
        className="pointer-events-none absolute inset-0"
      />

      {/* Interactive Cursor Proximity Highlight */}
      <div
        className="pointer-events-none absolute -inset-px transition-opacity duration-150"
        style={{
          background: `radial-gradient(220px circle at ${mousePos.x}px ${mousePos.y}px, rgba(16, 185, 129, 0.2), transparent 70%)`,
        }}
      />

      <div className="relative z-10 flex h-full flex-col justify-between">
        {children || (
          <div className="my-auto text-center font-mono">
            <span className="text-xs uppercase tracking-widest text-emerald-400">PARTICLE MATRIX</span>
            <h3 className="mt-2 text-xl font-bold text-white">Interactive Dot Grid</h3>
            <p className="mt-1 text-xs text-zinc-400">Move cursor to illuminate local coordinate field.</p>
          </div>
        )}
      </div>
    </div>
  )
}

import React from 'react'
import { cn } from '@/lib/utils'

export interface GridBackgroundProps {
  children?: React.ReactNode
  size?: 'sm' | 'md' | 'lg'
  withBeam?: boolean
  className?: string
}

export const GridBackground: React.FC<GridBackgroundProps> = ({
  children,
  size = 'md',
  withBeam = true,
  className,
}) => {
  const gridSizeMap = {
    sm: '24px 24px',
    md: '40px 40px',
    lg: '64px 64px',
  }

  return (
    <div className={cn('relative min-h-[300px] w-full overflow-hidden rounded-3xl border border-white/10 bg-[#070709] p-6', className)}>
      {/* Grid Pattern */}
      <div
        style={{
          backgroundSize: gridSizeMap[size],
          backgroundImage: `
            linear-gradient(to right, rgba(255, 255, 255, 0.06) 1px, transparent 1px),
            linear-gradient(to bottom, rgba(255, 255, 255, 0.06) 1px, transparent 1px)
