      {/* Radial fade mask */}
      <div className="pointer-events-none absolute inset-0 bg-radial-gradient from-transparent via-[#070709]/50 to-[#070709]" />

      {/* Scanning Beam */}
      {withBeam && (
        <div className="pointer-events-none absolute inset-x-0 h-24 -top-24 animate-[moveDown_8s_linear_infinite] bg-gradient-to-b from-transparent via-cyan-500/10 to-transparent" />
      )}

      <div className="relative z-10 flex h-full flex-col justify-between">
        {children || (
          <div className="my-auto text-center font-mono">
            <span className="text-xs uppercase tracking-widest text-cyan-400">ENGINEERING GRAPH</span>
            <h3 className="mt-2 text-xl font-bold text-white">Technical Coordinate Grid</h3>
            <p className="mt-1 text-xs text-zinc-400">Fine-lined hardware blueprint grid with scanning telemetry beam.</p>
          </div>
        )}
      </div>
    </div>
  )
}

import React, { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Lightning } from '@phosphor-icons/react';

interface ConfettiPiece {
  id: number;
  x: number;
  y: number;
  rotation: number;
  scale: number;
  color: string;
  shape: 'rect' | 'circle';
}

interface ConfettiButtonProps {
  children?: React.ReactNode;
  className?: string;
  particleCount?: number;
  colors?: string[];
  onClick?: () => void;
}

const DEFAULT_COLORS = ['#38bdf8', '#818cf8', '#c084fc', '#f472b6', '#34d399', '#fbbf24'];

export const ConfettiButton: React.FC<ConfettiButtonProps> = ({
  children = 'Celebrate Action',
  className = '',
  particleCount = 36,
  colors = DEFAULT_COLORS,
  onClick,
}) => {
  const [particles, setParticles] = useState<ConfettiPiece[]>([]);

  const triggerConfetti = (e: React.MouseEvent<HTMLButtonElement>) => {
    const rect = e.currentTarget.getBoundingClientRect();
    const centerX = rect.width / 2;
    const centerY = rect.height / 2;

    const newParticles: ConfettiPiece[] = Array.from({ length: particleCount }).map((_, i) => {
      const angle = (Math.PI * 2 * i) / particleCount + (Math.random() - 0.5) * 0.5;
      const velocity = 80 + Math.random() * 120;
      return {
        id: Date.now() + i,
        x: centerX + Math.cos(angle) * velocity,
        y: centerY + Math.sin(angle) * velocity - 30, // upward bias
        rotation: Math.random() * 720 - 360,
        scale: 0.5 + Math.random() * 0.8,
        color: colors[i % colors.length],
        shape: Math.random() > 0.4 ? 'rect' : 'circle',
      };
    });

    setParticles(newParticles);
    onClick?.();

    setTimeout(() => {
      setParticles([]);
    }, 1200);
  };

  return (
    <div className="relative inline-block overflow-visible">
      <motion.button
        whileHover={{ scale: 1.04 }}
        whileTap={{ scale: 0.94 }}
        onClick={triggerConfetti}
        className={`relative z-10 inline-flex items-center gap-2 px-6 py-3 rounded-full font-medium text-sm text-white bg-gradient-to-r from-violet-600 via-indigo-600 to-pink-500 shadow-lg shadow-indigo-500/25 hover:shadow-indigo-500/40 border border-white/20 transition-all select-none cursor-pointer ${className}`}
      >
        <Lightning size={18} weight="fill" className="text-yellow-300" />
        <span>{children}</span>
      </motion.button>

      <AnimatePresence>
        {particles.map((p) => (
          <motion.div
            key={p.id}
            initial={{ opacity: 1, x: 0, y: 0, scale: 0, rotate: 0 }}
            animate={{
              opacity: [1, 1, 0],
              x: p.x - 60,
              y: p.y - 30,
              scale: [0, p.scale, p.scale * 0.4],
              rotate: p.rotation,
            }}
            exit={{ opacity: 0 }}
            transition={{ duration: 1, ease: [0.25, 1, 0.5, 1] }}
            style={{
              position: 'absolute',
              top: '50%',
              left: '50%',
              width: p.shape === 'rect' ? 8 : 7,
              height: p.shape === 'rect' ? 14 : 7,
              backgroundColor: p.color,
              borderRadius: p.shape === 'circle' ? '50%' : 2,
              pointerEvents: 'none',
              zIndex: 30,
            }}
          />
        ))}
      </AnimatePresence>
    </div>
  );
};

import React, { useState } from 'react'
import { motion, AnimatePresence } from 'framer-motion'
import { Plus, X, ShareNetwork, Terminal, Heart } from '@phosphor-icons/react'
import { cn } from '@/lib/utils'

export interface FloatingActionButtonProps {
  label?: string
  className?: string
}

export const FloatingActionButton: React.FC<FloatingActionButtonProps> = ({
  className,
}) => {
  const [isOpen, setIsOpen] = useState(false)

  const actions = [
    { label: 'Run Compiler', icon: <Terminal size={16} /> },
    { label: 'Bookmark Symbol', icon: <Heart size={16} /> },
    { label: 'Share Workspace', icon: <ShareNetwork size={16} /> },
  ]

  return (
    <div className={cn('relative inline-flex flex-col items-center', className)}>
      <AnimatePresence>
        {isOpen && (
          <div className="absolute bottom-16 flex flex-col gap-2 mb-2 items-center">
            {actions.map((act, i) => (
              <motion.button
                key={act.label}
                initial={{ opacity: 0, y: 15, scale: 0.8 }}
                animate={{ opacity: 1, y: 0, scale: 1 }}
                exit={{ opacity: 0, y: 15, scale: 0.8 }}
                transition={{ delay: i * 0.05, duration: 0.2 }}
                onClick={() => setIsOpen(false)}
                title={act.label}
                className="flex items-center gap-2 rounded-full border border-white/15 bg-zinc-900/90 px-3.5 py-2 text-xs font-medium text-white shadow-xl backdrop-blur-md hover:bg-zinc-800 transition-colors whitespace-nowrap"
              >
                <span>{act.icon}</span>
                <span>{act.label}</span>
              </motion.button>
            ))}
          </div>
        )}
      </AnimatePresence>

      <motion.button
        whileTap={{ scale: 0.92 }}
        onClick={() => setIsOpen(!isOpen)}
        className="flex h-12 w-12 items-center justify-center rounded-full border border-white/20 bg-white text-zinc-950 shadow-2xl transition-transform hover:scale-105 focus:outline-none"
        aria-label="Toggle actions"
      >
        <motion.div animate={{ rotate: isOpen ? 45 : 0 }} transition={{ duration: 0.2 }}>
          <Plus size={22} weight="bold" />
        </motion.div>
      </motion.button>
    </div>
  )
}

import React from 'react'
import { motion } from 'framer-motion'
import { cn } from '@/lib/utils'

export interface GlowActionButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  children?: React.ReactNode
  glowColor?: 'cyan' | 'amber' | 'emerald' | 'purple'
  size?: 'sm' | 'md' | 'lg'
  className?: string
}

export const GlowActionButton: React.FC<GlowActionButtonProps> = ({
  children = 'Execute Action',
  glowColor = 'cyan',
  size = 'md',
  className,
  ...props
}) => {
  const glowStyles = {
    cyan: 'from-cyan-500/20 to-blue-500/20 group-hover:shadow-[0_0_35px_rgba(6,182,212,0.4)] border-cyan-500/30 text-cyan-200',
    amber: 'from-amber-500/20 to-orange-500/20 group-hover:shadow-[0_0_35px_rgba(245,158,11,0.4)] border-amber-500/30 text-amber-200',
    emerald: 'from-emerald-500/20 to-teal-500/20 group-hover:shadow-[0_0_35px_rgba(16,185,129,0.4)] border-emerald-500/30 text-emerald-200',
    purple: 'from-purple-500/20 to-pink-500/20 group-hover:shadow-[0_0_35px_rgba(168,85,247,0.4)] border-purple-500/30 text-purple-200',
  }

  const sizeStyles = {
    sm: 'px-4 py-2 text-xs',
    md: 'px-6 py-2.5 text-sm',
    lg: 'px-8 py-3.5 text-base',
  }

  return (
    <button
      className={cn(
        'group relative inline-flex items-center justify-center rounded-2xl border bg-gradient-to-b bg-zinc-950 font-medium transition-all duration-300 active:scale-95 shadow-lg',
        glowStyles[glowColor],
        sizeStyles[size],
