  const [opacity, setOpacity] = useState(0)

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    if (!divRef.current) return
    const div = divRef.current
    const rect = div.getBoundingClientRect()
    setPosition({ x: e.clientX - rect.left, y: e.clientY - rect.top })
  }

  return (
    <div
      ref={divRef}
      onMouseMove={handleMouseMove}
      onMouseEnter={() => setOpacity(1)}
      onMouseLeave={() => setOpacity(0)}
      className={cn(
        'relative overflow-hidden rounded-3xl border border-white/10 bg-zinc-950 p-6 text-white transition-colors hover:border-white/20',
        className
      )}
    >
      {/* Radial Spotlight Overlay */}
      <div
        className="pointer-events-none absolute -inset-px transition-opacity duration-300"
        style={{
          opacity,
          background: `radial-gradient(400px circle at ${position.x}px ${position.y}px, ${spotlightColor}, transparent 80%)`,
        }}
      />

      <div className="relative z-10">
        {icon && <div className="mb-4 inline-flex h-10 w-10 items-center justify-center rounded-xl bg-white/5 border border-white/10 text-white">{icon}</div>}
        <h4 className="text-base font-bold text-white tracking-tight">{title}</h4>
        <p className="mt-2 text-xs text-zinc-400 leading-relaxed">{description}</p>
        <div className="mt-4 flex items-center gap-2 font-mono text-[11px] text-zinc-500">
          <span className="h-1.5 w-1.5 rounded-full bg-cyan-400" />
          <span>Interactive Cursor Glow</span>
        </div>
      </div>
    </div>
  )
}

import React, { useState } from 'react';
import { Terminal, Copy, Check, Play } from '@phosphor-icons/react';

interface TerminalLine {
  type: 'input' | 'output' | 'success' | 'error';
  text: string;
}

export const TerminalCard: React.FC = () => {
  const [copied, setCopied] = useState(false);
  const [inputVal, setInputVal] = useState('');
  const [history, setHistory] = useState<TerminalLine[]>([
    { type: 'input', text: 'npx cook-ui add magnetic-dock' },
    { type: 'output', text: '✔ Resolving components and dependencies...' },
    { type: 'output', text: '✔ Generated components/ui/magnetic-dock.tsx' },
    { type: 'success', text: '✨ Ready in 342ms. Happy building!' },
  ]);

  const handleCopy = () => {
    navigator.clipboard.writeText('npx cook-ui add magnetic-dock');
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const handleCommand = (e: React.FormEvent) => {
    e.preventDefault();
    const cmd = inputVal.trim();
    if (!cmd) return;

    const newLines: TerminalLine[] = [...history, { type: 'input', text: cmd }];

    if (cmd === 'clear') {
      setHistory([]);
      setInputVal('');
      return;
    } else if (cmd === 'help') {
      newLines.push(
        { type: 'output', text: 'Available commands:' },
        { type: 'output', text: '  build     - trigger simulated project build' },
        { type: 'output', text: '  stats     - display component library metrics' },
        { type: 'output', text: '  clear     - wipe terminal buffer' }
      );
    } else if (cmd === 'build') {
      newLines.push(
        { type: 'output', text: 'vite v6.2.0 building for production...' },
        { type: 'output', text: '✓ 42 modules transformed.' },
        { type: 'success', text: 'dist/index.html   1.42 kB │ gzip: 0.65 kB' }
      );
    } else if (cmd === 'stats') {
      newLines.push(
        { type: 'output', text: 'Components: 42 active' },
        { type: 'output', text: 'FPS: 60 locked' },
        { type: 'success', text: 'Performance score: 100/100' }
      );
    } else {
      newLines.push({ type: 'error', text: `Command not found: ${cmd}. Type 'help' for commands.` });
    }

    setHistory(newLines);
    setInputVal('');
  };

  return (
    <div className="w-full max-w-lg rounded-2xl bg-zinc-950 border border-zinc-800 shadow-2xl overflow-hidden font-mono text-xs">
      {/* Terminal Titlebar */}
      <div className="flex items-center justify-between px-4 py-3 bg-zinc-900/90 border-b border-zinc-800">
        <div className="flex items-center gap-2">
          <div className="w-3 h-3 rounded-full bg-rose-500/80" />
          <div className="w-3 h-3 rounded-full bg-amber-500/80" />
          <div className="w-3 h-3 rounded-full bg-emerald-500/80" />
          <span className="ml-2 text-zinc-400 text-[11px] font-sans font-medium flex items-center gap-1.5">
            <Terminal size={14} className="text-zinc-500" />
            bash — 80x24
          </span>
        </div>

        <button
          onClick={handleCopy}
          className="flex items-center gap-1 text-[11px] font-sans text-zinc-400 hover:text-white transition-colors cursor-pointer"
        >
          {copied ? (
            <>
              <Check size={12} className="text-emerald-400" />
              <span className="text-emerald-400">Copied</span>
            </>
          ) : (
            <>
              <Copy size={12} />
              <span>Copy</span>
            </>
          )}
        </button>
      </div>

      {/* Terminal Body */}
      <div className="p-4 space-y-2 max-h-[220px] overflow-y-auto">
        {history.map((line, idx) => (
          <div key={idx} className="leading-relaxed">
            {line.type === 'input' && (
              <div className="flex items-center gap-2 text-zinc-200">
                <span className="text-cyan-400 font-bold">~</span>
                <span className="text-indigo-400">$</span>
                <span>{line.text}</span>
              </div>
            )}
            {line.type === 'output' && <div className="text-zinc-400 pl-4">{line.text}</div>}
            {line.type === 'success' && <div className="text-emerald-400 pl-4 font-medium">{line.text}</div>}
            {line.type === 'error' && <div className="text-rose-400 pl-4">{line.text}</div>}
          </div>
        ))}

        {/* Input prompt line */}
        <form onSubmit={handleCommand} className="flex items-center gap-2 text-zinc-200 pt-1">
          <span className="text-cyan-400 font-bold">~</span>
          <span className="text-indigo-400">$</span>
          <input
            type="text"
            value={inputVal}
            onChange={(e) => setInputVal(e.target.value)}
            placeholder="Type 'help', 'build', 'stats', 'clear'..."
            className="flex-1 bg-transparent text-zinc-100 placeholder-zinc-600 outline-none text-xs"
          />
          <button type="submit" className="text-zinc-500 hover:text-zinc-300">
            <Play size={10} weight="fill" />
          </button>
        </form>
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react'
import { cn } from '@/lib/utils'

export interface AsciiWaveProps {
  className?: string
  rows?: number
  cols?: number
}

export const AsciiWave: React.FC<AsciiWaveProps> = ({
  className,
  rows = 14,
  cols = 38,
}) => {
  const [output, setOutput] = useState<string[]>([])
  const frameRef = useRef(0)
  const mousePos = useRef({ x: 19, y: 7 })

  const chars = ' .:-=+*#%@'

  useEffect(() => {
    let animId: number

    const render = () => {
      frameRef.current += 0.05
      const lines: string[] = []

      for (let y = 0; y < rows; y++) {
        let line = ''
        for (let x = 0; x < cols; x++) {
          const dx = x - mousePos.current.x
          const dy = y - mousePos.current.y
          const dist = Math.sqrt(dx * dx + dy * dy)

          // Wave equation
          const wave1 = Math.sin(x * 0.2 + frameRef.current)
          const wave2 = Math.cos(y * 0.3 + frameRef.current * 0.8)
          const ripple = Math.sin(dist * 0.5 - frameRef.current * 2) * 0.4

          const val = (wave1 + wave2 + ripple + 2) / 4
          const charIdx = Math.floor(Math.max(0, Math.min(1, val)) * (chars.length - 1))
          line += chars[charIdx]
        }
        lines.push(line)
      }

      setOutput(lines)
      animId = requestAnimationFrame(render)
    }

    render()
    return () => cancelAnimationFrame(animId)
  }, [rows, cols])

  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
    const rect = e.currentTarget.getBoundingClientRect()
    const x = Math.floor(((e.clientX - rect.left) / rect.width) * cols)
    const y = Math.floor(((e.clientY - rect.top) / rect.height) * rows)
    mousePos.current = { x, y }
  }

  return (
    <div
      onMouseMove={handleMouseMove}
      className={cn(
        'relative overflow-hidden rounded-3xl border border-white/10 bg-[#060608] p-6 font-mono text-[10px] leading-[11px] text-emerald-400 select-none shadow-2xl flex flex-col items-center justify-center',
        className
      )}
    >
      <div className="absolute top-3 left-4 flex items-center gap-1.5 text-[9px] text-zinc-500 uppercase tracking-widest">
        <span className="h-1.5 w-1.5 rounded-full bg-emerald-400 animate-ping" />
        <span>ASCII WAVE GENERATOR</span>
      </div>

      <pre className="tracking-widest whitespace-pre overflow-hidden text-emerald-400/90 font-mono">
        {output.join('\n')}
      </pre>

      <div className="mt-3 text-[10px] text-zinc-500 font-mono">
        Interactive fluid simulation &bull; Hover to disturb
      </div>
    </div>
  )
}

