import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Play, Pause } from '@phosphor-icons/react';

interface SpectrumLoaderProps {
  className?: string;
  barCount?: number;
  color?: string;
  variant?: 'rainbow' | 'emerald' | 'violet';
}

export const SpectrumLoader: React.FC<SpectrumLoaderProps> = ({
  className = '',
  barCount = 16,
  variant = 'rainbow',
}) => {
  const [isPlaying, setIsPlaying] = useState(true);

  const getBarColor = (index: number) => {
    if (variant === 'rainbow') {
      const hue = 180 + (index / barCount) * 120;
      return `hsl(${hue}, 85%, 60%)`;
    }
    if (variant === 'emerald') {
      return '#10b981';
    }
    return '#8b5cf6';
  };

  return (
    <div className={`flex flex-col items-center justify-center p-6 gap-6 rounded-2xl bg-zinc-900/60 border border-white/10 backdrop-blur-md ${className}`}>
      {/* Equalizer Frequency Bars */}
      <div className="flex items-end justify-center gap-1.5 h-20 w-full max-w-[280px] px-4 py-2">
        {Array.from({ length: barCount }).map((_, i) => {
          // generate pseudo harmonic curve
          const baseHeight = 20 + Math.sin((i / barCount) * Math.PI) * 45;
          const minHeight = 12 + (i % 3) * 6;
          const duration = 0.5 + ((i * 7) % 5) * 0.12;

          return (
            <motion.div
              key={i}
              animate={
                isPlaying
                  ? {
                      height: [
                        `${minHeight}%`,
                        `${baseHeight}%`,
                        `${Math.min(100, baseHeight + 25)}%`,
                        `${minHeight + 10}%`,
                        `${baseHeight * 0.7}%`,
                      ],
                    }
                  : { height: '14%' }
              }
              transition={{
                duration,
                repeat: Infinity,
                repeatType: 'reverse',
                ease: 'easeInOut',
                delay: (i * 0.06) % 0.4,
              }}
              style={{
                backgroundColor: getBarColor(i),
                boxShadow: isPlaying ? `0 0 10px ${getBarColor(i)}` : 'none',
              }}
              className="w-2 rounded-full transition-all duration-300"
            />
          );
        })}
      </div>

      {/* Control pill */}
      <div className="flex items-center gap-3">
        <button
          onClick={() => setIsPlaying(!isPlaying)}
          className="inline-flex items-center gap-2 px-4 py-1.5 rounded-full text-xs font-mono font-medium text-zinc-300 bg-zinc-800 hover:bg-zinc-700 border border-white/10 transition-colors cursor-pointer"
        >
          {isPlaying ? (
            <>
              <Pause size={14} weight="fill" className="text-amber-400" />
              <span>PAUSE WAVE</span>
            </>
          ) : (
            <>
              <Play size={14} weight="fill" className="text-emerald-400" />
              <span>RESUME WAVE</span>
            </>
          )}
        </button>
        <span className="text-[11px] font-mono text-zinc-500 uppercase tracking-widest">
          {isPlaying ? '48.1 kHz Audio' : 'Muted'}
        </span>
      </div>
    </div>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { MagnifyingGlass, X, Lightning, ArrowRight } from '@phosphor-icons/react';

interface ExpandableSearchBarProps {
  className?: string;
  placeholder?: string;
  onSearch?: (query: string) => void;
  suggestions?: string[];
}

export const ExpandableSearchBar: React.FC<ExpandableSearchBarProps> = ({
  className = '',
  placeholder = 'Search components, hooks, animations...',
  onSearch,
  suggestions = ['Magnetic Dock', 'Border Beam', 'Sliding Number', 'Aurora Glow', 'Bento Block'],
}) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [query, setQuery] = useState('');
  const containerRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    const handleClickOutside = (e: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
        if (!query) setIsExpanded(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [query]);

  const handleSelectSuggestion = (item: string) => {
    setQuery(item);
    onSearch?.(item);
    setIsExpanded(false);
  };

  return (
    <div ref={containerRef} className={`relative z-20 w-full max-w-md ${className}`}>
      <motion.div
        animate={{
          width: isExpanded ? '100%' : '320px',
        }}
        transition={{ type: 'spring', stiffness: 350, damping: 28 }}
        className="relative mx-auto rounded-full bg-zinc-900/90 dark:bg-zinc-900/90 border border-white/15 backdrop-blur-xl shadow-xl overflow-hidden"
      >
        <div className="flex items-center px-4 py-2.5 gap-2.5">
          <MagnifyingGlass
            size={18}
            className={`transition-colors duration-200 ${
              isExpanded ? 'text-indigo-400' : 'text-zinc-400'
            }`}
          />
          <input
            ref={inputRef}
            type="text"
            value={query}
            onChange={(e) => {
              setQuery(e.target.value);
              onSearch?.(e.target.value);
            }}
            onFocus={() => setIsExpanded(true)}
            placeholder={placeholder}
            className="w-full bg-transparent text-sm text-zinc-100 placeholder-zinc-500 outline-none"
          />

          {query ? (
            <button
              onClick={() => {
                setQuery('');
                onSearch?.('');
                inputRef.current?.focus();
              }}
              className="text-zinc-400 hover:text-white p-1 rounded-full cursor-pointer"
            >
              <X size={14} />
            </button>
          ) : (
            <span className="hidden sm:inline-flex items-center gap-0.5 px-2 py-0.5 rounded text-[10px] font-mono font-medium text-zinc-400 bg-zinc-800 border border-zinc-700/60">
              ⌘K
            </span>
          )}
        </div>

        {/* Expanded Suggestions Dropdown */}
        <AnimatePresence>
          {isExpanded && (
            <motion.div
              initial={{ opacity: 0, height: 0 }}
              animate={{ opacity: 1, height: 'auto' }}
              exit={{ opacity: 0, height: 0 }}
              transition={{ duration: 0.2 }}
              className="px-4 pb-3 pt-1 border-t border-white/5 space-y-2"
            >
              <div className="flex items-center justify-between text-[11px] font-mono text-zinc-500 pt-1">
                <span>TRENDING QUERIES</span>
                <span className="flex items-center gap-1 text-indigo-400">
                  <Lightning size={12} weight="fill" /> POPULAR
                </span>
              </div>
              <div className="flex flex-wrap gap-1.5 pt-1">
                {suggestions.map((item) => (
                  <button
                    key={item}
                    onClick={() => handleSelectSuggestion(item)}
                    className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs text-zinc-300 bg-white/5 hover:bg-white/10 hover:text-white border border-white/10 transition-colors cursor-pointer"
                  >
                    <span>{item}</span>
                    <ArrowRight size={10} className="text-zinc-500" />
                  </button>
                ))}
              </div>
            </motion.div>
          )}
        </AnimatePresence>
      </motion.div>
    </div>
  );
};

import React, { useState } from 'react'
import { Check, X, Eye, EyeSlash, LockKey } from '@phosphor-icons/react'
import { cn } from '@/lib/utils'

export interface PasswordStrengthIndicatorProps {
  className?: string
}

export const PasswordStrengthIndicator: React.FC<PasswordStrengthIndicatorProps> = ({ className }) => {
  const [password, setPassword] = useState('')
  const [show, setShow] = useState(false)

  const hasLength = password.length >= 8
  const hasUpper = /[A-Z]/.test(password)
  const hasNumber = /[0-9]/.test(password)
  const hasSpecial = /[^A-Za-z0-9]/.test(password)

  const score = [hasLength, hasUpper, hasNumber, hasSpecial].filter(Boolean).length

  const strengthLabels = ['Empty', 'Weak', 'Moderate', 'Strong', 'Cryptographic']
  const strengthColors = ['bg-zinc-800', 'bg-rose-500', 'bg-amber-500', 'bg-blue-500', 'bg-emerald-500']

  return (
    <div className={cn('w-full max-w-sm rounded-3xl border border-white/10 bg-zinc-950 p-5 font-mono text-xs text-white shadow-2xl', className)}>
      <div className="flex items-center justify-between text-zinc-400 pb-2 border-b border-white/5 mb-3">
        <span className="text-[10px] uppercase tracking-widest">SECURITY TELEMETRY</span>
        <span className="text-zinc-500 text-[10px]">ENTROPY METER</span>
      </div>

      <div className="relative flex items-center">
        <LockKey size={16} className="absolute left-3 text-zinc-500" />
        <input
          type={show ? 'text' : 'password'}
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          placeholder="Enter secret token..."
          className="w-full rounded-xl border border-white/10 bg-zinc-900/80 py-2.5 pl-9 pr-10 text-xs text-white placeholder-zinc-600 focus:outline-none focus:border-white/30"
        />
        <button
          type="button"
          onClick={() => setShow(!show)}
          className="absolute right-3 text-zinc-400 hover:text-white"
        >
          {show ? <EyeSlash size={16} /> : <Eye size={16} />}
        </button>
      </div>

      {/* Strength Bars */}
      <div className="mt-3 flex gap-1.5 h-1.5 w-full">
        {[0, 1, 2, 3].map((idx) => (
          <div
            key={idx}
            className={`h-full flex-1 rounded-full transition-all duration-300 ${
              score > idx ? strengthColors[score] : 'bg-zinc-800'
            }`}
          />
        ))}
      </div>

      <div className="mt-2 flex items-center justify-between text-[10px]">
        <span className="text-zinc-500">Security Strength:</span>
        <span className={score === 4 ? 'text-emerald-400 font-bold' : 'text-zinc-300'}>
          {strengthLabels[score]}
        </span>
      </div>

      {/* Rules Grid */}
      <div className="mt-4 grid grid-cols-2 gap-2 text-[10px]">
        <div className={`flex items-center gap-1.5 ${hasLength ? 'text-emerald-400' : 'text-zinc-500'}`}>
          {hasLength ? <Check size={12} weight="bold" /> : <X size={12} />}
          <span>8+ Characters</span>
        </div>
        <div className={`flex items-center gap-1.5 ${hasUpper ? 'text-emerald-400' : 'text-zinc-500'}`}>
          {hasUpper ? <Check size={12} weight="bold" /> : <X size={12} />}
