import React from 'react'
import { motion } from 'framer-motion'
import { cn } from '@/lib/utils'

export interface TextRevealProps {
  text?: string
  delay?: number
  className?: string
}

export const TextReveal: React.FC<TextRevealProps> = ({
  text = 'Deterministic Software Synthesis Engine',
  delay = 0,
  className,
}) => {
  const words = text.split(' ')

  const container = {
    hidden: { opacity: 0 },
    visible: (i = 1) => ({
      opacity: 1,
      transition: { staggerChildren: 0.08, delayChildren: 0.04 * i + delay },
    }),
  }

  const child = {
    visible: {
      opacity: 1,
      y: 0,
      filter: 'blur(0px)',
      transition: {
        type: 'spring' as const,
        damping: 18,
        stiffness: 120,
      },
    },
    hidden: {
      opacity: 0,
      y: 20,
      filter: 'blur(4px)',
    },
  }

  return (
    <motion.div
      variants={container}
      initial="hidden"
      whileInView="visible"
      viewport={{ once: false }}
      className={cn('flex flex-wrap gap-x-2 gap-y-1 font-bold text-white', className)}
    >
      {words.map((word, index) => (
        <motion.span
          key={`${word}-${index}`}
          variants={child}
          className="inline-block"
        >
          {word}
        </motion.span>
      ))}
    </motion.div>
  )
}

import React, { useState, useEffect } from 'react'
import { cn } from '@/lib/utils'

export interface TypingTextProps {
  words?: string[]
  speed?: number
  delay?: number
  className?: string
}

export const TypingText: React.FC<TypingTextProps> = ({
  words = ['Synthesizing Raft Cluster...', 'Proving Invariant Logic...', 'Emitting WASM Bytecode...', 'Zero Hallucinations.'],
  speed = 80,
  delay = 1500,
  className,
}) => {
  const [wordIndex, setWordIndex] = useState(0)
  const [currentText, setCurrentText] = useState('')
  const [isDeleting, setIsDeleting] = useState(false)

  useEffect(() => {
    const fullWord = words[wordIndex % words.length]

    const timeout = setTimeout(
      () => {
        if (!isDeleting) {
          setCurrentText(fullWord.substring(0, currentText.length + 1))
          if (currentText === fullWord) {
            setTimeout(() => setIsDeleting(true), delay)
          }
        } else {
          setCurrentText(fullWord.substring(0, currentText.length - 1))
          if (currentText === '') {
            setIsDeleting(false)
            setWordIndex((prev) => prev + 1)
          }
        }
      },
      isDeleting ? speed / 2 : speed
    )

    return () => clearTimeout(timeout)
  }, [currentText, isDeleting, wordIndex, words, speed, delay])

  return (
    <div className={cn('inline-flex items-center font-mono text-white', className)}>
      <span>{currentText}</span>
      <span className="ml-1 inline-block h-4 w-2 bg-emerald-400 animate-[pulse_0.8s_ease-in-out_infinite]" />
    </div>
  )
}
